export const MESSAGING_ADAPTER = "/* Runtime adapter for the unmodified messaging handoff. Runs in its lexical scope. */\nlet canInvoke = false;\nlet pendingSend = null;\nlet sequence = 0;\nlet booted = false;\nlet themeMode = 'dark';\nconst originalBoot = boot;\nboot = function(data, args, mode) {\n  if (booted) return;\n  booted = true;\n  themeMode = mode;\n  originalBoot(data, args, mode);\n  // Keep late host capability/theme updates from resetting a user's draft.\n  const name = document.querySelector('#gname');\n  if (name) name.addEventListener('input', () => { A.groupName = name.value; });\n};\n// Capture first: the host often supplies {} data and no args for result widgets.\n// Fall back to the server's baked live payload, never the package's demo roster.\naddEventListener('message', event => {\n  if (event.data?.type !== 'voiceos:init') return;\n  event.stopImmediatePropagation();\n  if (event.source !== parent) return;\n  const m = event.data;\n  canInvoke = m.capabilities?.invokeTool === true;\n  themeMode = m.theme?.mode || themeMode;\n  document.documentElement.dataset.theme = themeMode;\n  inited = true;\n  boot(m.data && Object.keys(m.data).length ? m.data : DEMO.data,\n    { ...DEMO.args, ...m.args }, themeMode);\n}, true);\n\nfunction sendStatus(message, bad = false) {\n  let status = document.querySelector('#send-status');\n  if (!status) {\n    status = document.createElement('div');\n    status.id = 'send-status'; status.className = 'sys';\n    status.setAttribute('role', 'status');\n    document.querySelector('#c').before(status);\n  }\n  status.textContent = message;\n  status.style.color = bad ? 'var(--bad)' : 'var(--ink-3)';\n  report();\n}\nfunction unpackResult(result) {\n  if (result?.isError) throw new Error('The send failed. Your draft is still here.');\n  if (result?.structuredContent) return result.structuredContent;\n  const text = result?.content?.find(block => block.type === 'text')?.text;\n  return typeof text === 'string' ? JSON.parse(text) : result;\n}\nfunction finishSend(status, result, error) {\n  const pending = pendingSend;\n  if (!pending) return;\n  clearTimeout(pending.timer);\n  pendingSend = null;\n  if (status === 'completed') {\n    try {\n      const body = unpackResult(result);\n      if (body?.sent !== true) throw new Error(body?.message || 'The send was not confirmed.');\n      const receipt = body.receipt;\n      if (!receipt?.html) {\n        // Completed is final even if the host omitted its large result. Never resend.\n        sendStatus('Sent. Open the conversation to see the latest messages.');\n        return;\n      }\n      stage('message', '');\n      // Host toolResult deliberately strips _voiceos_glance. The server also\n      // returns this receipt as data so the calling widget can show 1D / 1K.\n      const html = receipt.html.replace('<meta charset=\"utf-8\" />',\n        '<meta charset=\"utf-8\" /><meta name=\"voiceos-receipt-theme\" content=\"' + themeMode + '\">');\n      document.open(); document.write(html); document.close();\n      return;\n    } catch (cause) { error = cause.message; status = 'failed'; }\n  }\n  if (status === 'unknown') {\n    sendStatus('Delivery is unconfirmed. Check Grok Bot before sending again.', true);\n    return; // Keep send locked: a timed-out request may already have acted.\n  }\n  document.querySelectorAll('#v-thread input, #v-thread button').forEach(el => el.disabled = false);\n  const input = document.querySelector('#msg');\n  document.querySelector('.send').disabled = !input.value.trim();\n  sendStatus(status === 'cancelled' ? 'Cancelled — your draft is still here.' : (error || 'Not sent. Your draft is still here.'), true);\n}\naddEventListener('message', event => {\n  if (event.source !== parent || event.data?.type !== 'voiceos:toolResult') return;\n  const m = event.data;\n  if (!pendingSend || pendingSend.requestId !== m.requestId) return;\n  if (!['completed', 'failed', 'cancelled', 'unknown'].includes(m.status)) return;\n  if (m.status === 'completed' && m.resultOmitted) {\n    clearTimeout(pendingSend.timer); pendingSend = null;\n    sendStatus('Sent. Open the conversation to see the latest messages.');\n    return;\n  }\n  finishSend(m.status, m.result, m.error);\n});\n// Replace the demo's form submission callback, retaining its exact composer UI.\n// VoiceOS uses allow-scripts without allow-forms, so use click / Enter events.\nwireComposer = function(root) {\n  const form = root.querySelector('#compose');\n  form.querySelector('.plus')?.remove();\n  const input = form.querySelector('#msg');\n  const button = form.querySelector('.send');\n  button.type = 'button';\n  let locked = false;\n  const go = () => {\n    const message = input.value.trim();\n    if (!message || pendingSend || locked) return;\n    if (!canInvoke) { sendStatus('Sending is unavailable in this host. Your draft is still here.', true); return; }\n    if (isGroup && members.length < (G ? 1 : 2)) {\n      sendStatus(G ? 'Keep at least one bot in this group.' : 'Add at least two bots to start a group.', true); return;\n    }\n    // grokbot_card_send: same handlers as grokbot_send / grokbot_group, but no\n    // manifest `confirmation` block — so the host never floats its \"Confirm\n    // action\" dialog over the card. Typing + send here IS the user's approval.\n    const args = isGroup\n      ? { ...(G ? { group: G.id } : {}), members: members.slice(), groupName: document.querySelector('#gname').value, message }\n      : { bot: A.bot, message };\n    stage('message', message);\n    if (isGroup) { stage('groupName', args.groupName); stage('members', args.members); }\n    const requestId = 'send_' + Date.now() + '_' + (++sequence);\n    document.querySelectorAll('#v-thread input, #v-thread button').forEach(el => el.disabled = true);\n    sendStatus('Sending…');\n    pendingSend = { requestId, timer: setTimeout(() => { locked = true; finishSend('unknown'); }, 65000) };\n    parent.postMessage({ type: 'voiceos:invokeTool', name: 'grokbot_card_send', args, requestId }, '*');\n  };\n  form.addEventListener('submit', event => event.preventDefault());\n  input.addEventListener('input', () => { button.disabled = !input.value.trim(); });\n  button.addEventListener('click', event => { event.preventDefault(); go(); });\n  input.addEventListener('keydown', event => {\n    if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) { event.preventDefault(); go(); }\n  });\n};\n// Group avatars remain a usable member-picker even with no selected members.\nif (typeof stackHtml === 'function') {\n  const originalStack = stackHtml;\n  stackHtml = function() {\n    return members.length ? originalStack() : '<button class=\"stack\" id=\"stack\" aria-label=\"Members\">+</button>';\n  };\n}\nconst savedTheme = document.querySelector('meta[name=\"voiceos-receipt-theme\"]')?.content;\nif (savedTheme) themeMode = savedTheme;\n// The package's fallback is useful for standalone files; production boots from\n// the injected payload immediately so the card cannot flash sample content.\nboot(DEMO.data, DEMO.args, themeMode);\n";
export const CONFIRMATION_ADAPTER = "/* Confirmation bridge for the unchanged thread.html handoff.\n * VoiceOS owns approval: this iframe stages edits, never invokes a send tool.\n * The host's floating arrow occupies the composer slot reserved by the CSS.\n */\nconst packageBoot = boot;\nlet confirmationBooted = false;\nconst normalizeName = value => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');\nfunction lookup(list, value) {\n  const id = list.find(item => item.id === value);\n  if (id) return id;\n  const name = normalizeName(value);\n  const exact = name ? list.filter(item => normalizeName(item.name) === name) : [];\n  if (exact.length === 1) return exact[0];\n  return null;\n}\nfunction confirmationPayload(data, args) {\n  // The read-only lookup passes a fresh roster through host arguments. The\n  // frozen manifest remains a fallback for cards opened without voice lookup.\n  if (args.confirmationContext !== undefined) {\n    try {\n      const live = JSON.parse(args.confirmationContext);\n      if (!Array.isArray(live.bots) || !Array.isArray(live.groups) ||\n          ![...live.bots, ...live.groups].every(b => b && typeof b.id === 'string' && typeof b.name === 'string') ||\n          !live.groups.every(g => Array.isArray(g.members))) throw new Error('Invalid roster');\n      data = { ...data, bots: live.bots, groups: live.groups, threads: live.threads || {} };\n    } catch {\n      return { data, args, error: 'Could not verify the recipients. Close this card and try the message again.' };\n    }\n  }\n  const d = { ...data, bots: [...(data.bots || [])], groups: [...(data.groups || [])] };\n  const a = { ...args };\n  if (data.tool === 'grokbot_send') {\n    const bot = lookup(d.bots, a.bot);\n    if (bot) a.bot = bot.id;\n    else return { data: d, args: a, error: 'That bot could not be found. If you just created it, it may not be available yet. Close this card and try again.' };\n    d.thread = data.threads?.[a.bot] || [];\n  } else {\n    let group = a.group ? lookup(d.groups, a.group) : null;\n    if (a.group && !group) return { data: d, args: a, error: 'That group could not be found. Close this card and check its name.' };\n    const tokens = Array.isArray(a.members) ? a.members : String(a.members || '').split(',').map(x => x.trim()).filter(Boolean);\n    const requested = a.members === undefined && group ? group.members : tokens;\n    if (requested.some(token => !lookup(d.bots, token))) return { data: d, args: a, error: 'One or more bots could not be found. Close this card and check the recipients.' };\n    a.members = a.members === undefined && group ? group.members.slice() : tokens.map(token => {\n      const bot = lookup(d.bots, token);\n      if (bot) return bot.id;\n      return token;\n    });\n    a.members = [...new Set(a.members)];\n    if (!group && !a.group && a.members.length >= 2) {\n      const matches = d.groups.filter(g => g.members.length === a.members.length && g.members.every(id => a.members.includes(id)));\n      if (matches.length === 1) group = matches[0];\n    }\n    if (group) {\n      a.group = group.id;\n      if (a.groupName === undefined) a.groupName = group.name;\n      // The package uses G.members, so overlay the requested edits there too.\n      d.groups = d.groups.map(g => g.id === group.id ? { ...g, members: a.members, thread: data.threads?.[g.id] || [] } : g);\n    }\n  }\n  return { data: d, args: a };\n}\n// Suppress the package's standalone fallback until real tool arguments arrive.\nboot = function() {};\nstage = function(key, value) {\n  // ConfirmationWidget accepts primitive values only; arrays are ignored.\n  if (key === 'members' && Array.isArray(value)) value = value.join(',');\n  parent.postMessage({ type: 'voiceos:updateInput', key, value }, '*');\n};\nwireComposer = function(root) {\n  const form = root.querySelector('#compose');\n  form.querySelector('.plus')?.remove();\n  const button = form.querySelector('.send');\n  button.type = 'button';\n  button.hidden = true;\n  form.addEventListener('submit', event => event.preventDefault());\n};\naddEventListener('message', event => {\n  if (event.data?.type !== 'voiceos:init') return;\n  event.stopImmediatePropagation();\n  if (event.source !== parent || confirmationBooted) return;\n  confirmationBooted = true;\n  inited = true;\n  document.documentElement.classList.add('thread-confirmation');\n  const payload = confirmationPayload(DEMO.data, event.data.args || {});\n  if (payload.error) {\n    // Never boot the package's fallback thread for an unresolved recipient.\n    // The host owns its approval button; clearing the draft prevents a send.\n    stage('message', '');\n    const status = document.createElement('p');\n    status.textContent = payload.error;\n    status.setAttribute('role', 'status');\n    status.style.cssText = 'padding:24px;color:var(--ink-2);font:14px/1.5 system-ui';\n    document.body.replaceChildren(status);\n    report();\n    return;\n  }\n  packageBoot(payload.data, payload.args, event.data.theme?.mode || 'dark');\n  for (const key of ['bot', 'group', 'members', 'groupName']) {\n    if (payload.args[key] !== undefined) stage(key, payload.args[key]);\n  }\n  const name = document.querySelector('#gname');\n  if (name) name.addEventListener('input', () => { A.groupName = name.value; });\n}, true);\n";
export const MESSAGING_CSS = "/* Only frame bounds; the handoff's visual styles and animation engine stay intact. */\n#v-thread{max-height:420px;display:flex;flex-direction:column;overflow:hidden}\n#v-thread[hidden],#v-members[hidden]{display:none}\n#v-thread>.hd,#v-thread>#c{flex-shrink:0}\n#v-thread>#msgs{min-height:0;flex:1 1 auto;overflow-y:auto;overflow-wrap:anywhere}\n#v-members{max-height:420px;overflow-y:auto;overscroll-behavior:contain}\n#v-members>.hd{position:sticky;top:0;z-index:2;background:var(--card)}\n#stack{max-width:110px;flex-wrap:wrap;row-gap:3px;flex-shrink:0}\n#stack:empty{min-width:30px;min-height:30px}\n#hd .mark{flex-shrink:0}\n.mrow .t2{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n#send-status{padding:0 14px;max-height:48px;overflow-y:auto;flex-shrink:0}\n#msgs{overflow-wrap:anywhere;max-height:268px;overflow-y:auto}\n/* VoiceOS positions its 30px approval button 12px right / 10px bottom.\n   Reserve that exact slot; the iframe has no API for approving a tool itself. */\n.thread-confirmation .compose{margin-bottom:4px;padding-right:54px}\n.thread-confirmation .compose .send{display:none}\n.thread-confirmation #v-members{padding-bottom:46px}\n";
